/**
 * Types of the test-spec lane of a Request (docs/integrate/TDD-REQ-TESTSPEC-001).
 *
 * Test specs are generated by tdd-agent from the moment Plan generation begins, beside the Plan; they never change the Request
 * status. Execution waits for them at the join (REQUEST_TESTSPEC_GATE).
 *
 * @module shared/request-testspec-types
 */

export type TestSpecStatus =
  | 'pending'
  | 'starting'
  | 'running'
  | 'completed'
  | 'blocked'
  | 'failed'
  | 'skipped'
  | 'cancelled'
  | 'unknown'

export type TestSpecDocumentName = 'requirements' | 'design' | 'cases'

export type TestSpecGap = {
  code: string
  missing: string
  question: string
  owner: string
  blocks: number
}

export type TestSpecSummary = {
  feature: string
  version: number
  status: string
  counts: { requirements: number; cases: number; gaps: number }
  files: string[]
  gaps: TestSpecGap[]
  notes: string[]
}

export type TestSpecRun = {
  id: string
  attempt: number
  status: TestSpecStatus
  reasonCode?: string
  reasonMessage?: string
  contextMode?: 'solution' | 'plan' | string
  contextRef?: string
  tddRunId?: string
  feature?: string
  summary: TestSpecSummary
  startedBy?: string
  startedAt?: string
  finishedAt?: string
  updatedAt?: string
}

/** What execution does about the lane right now: go, wait (still generating) or stop (ended without test specs, gate require). */
export type TestSpecJoin = 'go' | 'wait' | 'stop'

export type TestSpecs = {
  requestId: string
  /** False when the deployment does not generate test specs: the panel shows nothing. */
  enabled: boolean
  current: TestSpecRun | null
  history: TestSpecRun[]
  /** wait, require, warn or off; empty when the gate is not reported. */
  gate: string
  join: TestSpecJoin
  /** Execution goes on although the test specs are not usable. */
  joinWarn: boolean
  /** Reason code behind a wait that ran out or a lane that ended without test specs. */
  joinCause: string
}

export type TestSpecDocumentPage = {
  document: string
  version: number
  status: string
  length: number
  text: string
  hasNext: boolean
  next: number
}
